package com.example.starter.margin.domain;

/**
 * 追加保证金入账结果。
 */
public enum DepositResult {
    /** 首次入账成功 */
    ACCEPTED,
    /** 同 requestId 重放，返回首次结果，未重复入账 */
    REPLAYED,
    /** 强平已开始执行，迟到入账计入余下负债重算 */
    APPLIED_TO_REMAINING,
    /** 账户已全额强平终结，入账不再改变结果 */
    REJECTED_CLOSED
}

package com.example.starter.margin.domain;

/**
 * 强平作业状态。指令生成后：PENDING 可被达标入账撤销；EXECUTED 为终态不可撤销。
 */
public enum JobStatus {
    /** 待发强平（低于 110% 或追保逾期后生成，尚未开始执行） */
    PENDING,
    /** 待发期间入账使比例达标，作业撤销 */
    CANCELLED,
    /** 已执行（终态，不可撤销） */
    EXECUTED
}

package com.example.starter.margin.domain;

/**
 * 触发强制平仓的原因。
 */
public enum LiquidationReason {
    /** 维持担保比例低于 110%，跳过追保直接强平 */
    BELOW_110,
    /** 追保通知逾期未补足 */
    OVERDUE
}

package com.example.starter.margin.domain;

/**
 * 单笔负债状态。
 */
public enum LiabilityStatus {
    /** 未偿还（强平排序对象） */
    OUTSTANDING,
    /** 已偿还（强平处置或正常还款） */
    REPAID
}

