/**
 * 计算在当前总资产 A、总负债 L 下，处置担保物偿还 r 使比例严格高于 140% 所需的最小偿还额
 * （精确到分，HALF/UP 口径一致并做越线校正）。
 * 由 (A-r)/(L-r) &gt; 1.40 推得 r &gt; (1.4L - A)/0.4。
 *
 * @param debtCap 本笔负债未偿上限；若全额偿还仍不能越线返回 null（继续平下一笔）
 */
private BigDecimal minimalRepayToCross(BigDecimal assets, BigDecimal totalLiabilities, BigDecimal debtCap) {
    BigDecimal gap = RiskRules.MAINTENANCE_LINE.multiply(totalLiabilities).subtract(assets);
    if (gap.signum() <= 0) {
        // 当前比例已高于 140%，无需偿还
        return BigDecimal.ZERO.setScale(2);
    }
    BigDecimal raw = gap.divide(new BigDecimal("0.4"), 8, RoundingMode.HALF_UP);
    BigDecimal r = raw.setScale(2, RoundingMode.UP);
    // 严格高于：取整后若仍未越线（理论上 UP 已够，防御性逐分校正）
    BigDecimal cent = BigDecimal.ONE.movePointLeft(2);
    int guard = 0;
    while (!RiskRules.ratioGreaterThan(assets.subtract(r), totalLiabilities.subtract(r),
            RiskRules.MAINTENANCE_LINE) && guard++ < 10) {
        r = r.add(cent);
    }
    if (r.compareTo(debtCap) > 0) {
        return null;
    }
    return r;
}

