/** 强平处置：部分/全额偿还一笔负债。全额置 REPAID，部分仅减少未偿金额。 */
public void repayLiability(String liabilityNo, BigDecimal repayAmount, Instant repaidAt) {
    int updated = jdbc.update(
            "UPDATE liability SET outstanding_amount = outstanding_amount - ?, "
                    + "status = CASE WHEN outstanding_amount - ? <= 0 THEN 'REPAID' ELSE status END, "
                    + "repaid_at = CASE WHEN outstanding_amount - ? <= 0 THEN ? ELSE repaid_at END "
                    + "WHERE liability_no = ? AND status = 'OUTSTANDING'",
            repayAmount, repayAmount, repayAmount, Timestamp.from(repaidAt), liabilityNo);
    if (updated != 1) {
        throw new IllegalStateException("强平偿还负债失败或负债已结清: " + liabilityNo);
    }
}

