package com.example.starter.margin.api;

import com.example.starter.margin.repo.AccountDataRepository;
import com.example.starter.margin.support.MarginClock;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;

import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 端到端 HTTP 测试：真实 Spring MVC + H2，覆盖装配、追保、幂等入账、409/400 错误语义、
 * 逾期强平阶梯与恢复的完整调用链。
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class MarginControllerHttpTest {

    @LocalServerPort
    private int port;
    @Autowired
    private TestRestTemplate rest;
    @Autowired
    private AccountDataRepository accountData;
    @Autowired
    private MarginClock clock;

    @BeforeEach
    void clean() {
        accountData.deleteAll();
        clock.reset();
    }

    private String url(String path) {
        return "http://localhost:" + port + "/api/margin" + path;
    }

    private HttpHeaders json() {
        HttpHeaders h = new HttpHeaders();
        h.setContentType(MediaType.APPLICATION_JSON);
        return h;
    }

    @Test
    void fullFlow_marginCall_deposit_overdueLiquidation_andRecovery() {
        // 1) 装配合成账户：资产 1100、负债 500/300/200（恰好 110%）
        String setupBody = """
                {
                  "accountNo":"W1","clientName":"王五","currency":"CNY","totalAssets":"1100.00",
                  "liabilities":[
                    {"liabilityNo":"L-BIG","amount":"500.00"},
                    {"liabilityNo":"L-MID","amount":"300.00"},
                    {"liabilityNo":"L-SML","amount":"200.00"}
                  ]
                }
                """;
        ResponseEntity<Map> created = rest.postForEntity(url("/accounts"),
                new HttpEntity<>(setupBody, json()), Map.class);
        assertThat(created.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(created.getBody()).containsEntry("ratio", 1.1000);

        // 2) 评估：恰好 110% 走追保
        @SuppressWarnings("unchecked")
        Map<String, Object> assessed = rest.postForEntity(url("/accounts/W1/assess"),
                new HttpEntity<>("", json()), Map.class).getBody();
        assertThat(assessed).containsEntry("action", "MARGIN_NOTICE");
        assertThat(assessed.get("noticeCreated")).isEqualTo(true);
        String deadline = (String) assessed.get("deadline");
        assertThat(deadline).isNotNull();

        // 3) 幂等入账：先一笔不足额（100 元 → 1200/1000=120%）
        String smallDeposit = """
                {"requestId":"D1","accountNo":"W1","amount":"100.00","currency":"CNY"}""";
        @SuppressWarnings("unchecked")
        Map<String, Object> d1 = rest.postForEntity(url("/deposits"),
                new HttpEntity<>(smallDeposit, json()), Map.class).getBody();
        assertThat(d1.get("noticeResolved")).isEqualTo(false);

        // 4) 同键异参 → 409
        String conflict = """
                {"requestId":"D1","accountNo":"W1","amount":"500.00","currency":"CNY"}""";
        ResponseEntity<String> conflictResp = rest.postForEntity(url("/deposits"),
                new HttpEntity<>(conflict, json()), String.class);
        assertThat(conflictResp.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);

        // 5) 参数非法（金额 0）→ 400
        String bad = """
                {"requestId":"D2","accountNo":"W1","amount":"0","currency":"CNY"}""";
        ResponseEntity<String> badResp = rest.postForEntity(url("/deposits"),
                new HttpEntity<>(bad, json()), String.class);
        assertThat(badResp.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);

        // 6) 拨动时钟到截止时刻 → 逾期生成强平
        rest.put("http://localhost:" + port + "/api/margin/admin/clock",
                new HttpEntity<>("{\"iso\":\"" + deadline + "\"}", json()));
        @SuppressWarnings("unchecked")
        Map<String, Object> overdue = rest.postForEntity(url("/accounts/W1/overdue"),
                new HttpEntity<>("", json()), Map.class).getBody();
        assertThat(overdue).containsEntry("action", "LIQUIDATE");
        Number jobIdNum = (Number) overdue.get("jobId");
        long jobId = jobIdNum.longValue();

        // 7) 执行阶梯强平：先全额平 500，再部分平 250，比例回到 140%
        @SuppressWarnings("unchecked")
        Map<String, Object> executed = rest.postForEntity(url("/liquidations/" + jobId + "/execute"),
                new HttpEntity<>("", json()), Map.class).getBody();
        assertThat(executed).containsEntry("status", "EXECUTED");
        assertThat(executed.get("finalRatio")).isEqualTo(1.4000);
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> items = (List<Map<String, Object>>) executed.get("items");
        assertThat(items).hasSize(2);
        assertThat(items.get(0).get("liabilityNo")).isEqualTo("L-BIG");
        assertThat(items.get(0).get("repaidAmount")).isEqualTo(500.00);
        assertThat(items.get(1).get("liabilityNo")).isEqualTo("L-MID");
        assertThat(items.get(1).get("repaidAmount")).isEqualTo(250.00);

        // 8) 恢复：迟到/后续保证金计入余下负债（200+50 未偿），查询账户比例恢复
        String recovery = """
                {"requestId":"D3","accountNo":"W1","amount":"100.00","currency":"CNY"}""";
        @SuppressWarnings("unchecked")
        Map<String, Object> d3 = rest.postForEntity(url("/deposits"),
                new HttpEntity<>(recovery, json()), Map.class).getBody();
        assertThat(d3.get("result")).isEqualTo("APPLIED_TO_REMAINING");
        // 强平后资产 350、余下负债 250；再加 100 → 450/250 = 180%
        assertThat(d3.get("ratioAfter")).isEqualTo(1.8000);

        @SuppressWarnings("unchecked")
        Map<String, Object> view = rest.getForEntity(url("/accounts/W1"), Map.class).getBody();
        assertThat(view.get("ratio")).isEqualTo(1.8000);
        assertThat(view.get("executedJobStatus")).isEqualTo("EXECUTED");

        // 9) 终态作业只读查询，不产生新指令
        @SuppressWarnings("unchecked")
        Map<String, Object> jobView = rest.getForEntity(url("/liquidations/" + jobId), Map.class).getBody();
        assertThat(jobView).containsEntry("status", "EXECUTED");
        @SuppressWarnings("unchecked")
        List<Map<String, Object>> storedItems = (List<Map<String, Object>>) jobView.get("items");
        assertThat(storedItems).hasSize(2);
    }

    @Test
    void unknownAccountReturns404Or400AndDuplicateSetupRejected() {
        String setupBody = """
                {"accountNo":"W2","clientName":"钱六","currency":"CNY","totalAssets":"1500.00",
                 "liabilities":[{"liabilityNo":"L1","amount":"1000.00"}]}""";
        rest.postForEntity(url("/accounts"), new HttpEntity<>(setupBody, json()), Map.class);
        // 重复装配 → 400
        ResponseEntity<String> dup = rest.postForEntity(url("/accounts"),
                new HttpEntity<>(setupBody, json()), String.class);
        assertThat(dup.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        // 不存在账户查询 → 400
        ResponseEntity<String> missing = rest.getForEntity(url("/accounts/NOPE"), String.class);
        assertThat(missing.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
    }
}

